body {
    background-color: #121212;
    color: #e0e0e0;
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
    margin: 0;
}

.container {
    background-color: #1e1e1e;
    padding: 2rem;
    border-radius: 8px;
    box-shadow: 0 4px 6px rgba(0, 0, 0, 0.3);
    width: 100%;
    max-width: 400px;
}

h1 {
    font-size: 1.5rem;
    margin-bottom: 1.5rem;
    color: #ffffff;
}

.form-field {
    margin-bottom: 1.5rem;
}

.radio-group {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.radio-option {
    display: flex;
    align-items: center;
    cursor: pointer;
    padding: 0.5rem;
    border-radius: 4px;
    transition: background-color 0.2s;
}

.radio-option:hover {
    background-color: #2c2c2c;
}

.radio-option input[type="radio"] {
    margin-right: 0.75rem;
    width: 1.2rem;
    height: 1.2rem;
    cursor: pointer;
    accent-color: #bb86fc;
}

.radio-label {
    font-size: 1rem;
    color: #e0e0e0;
}

button[type="submit"] {
    background-color: #bb86fc;
    color: #000000;
    border: none;
    padding: 0.75rem 1.5rem;
    font-size: 1rem;
    font-weight: 600;
    border-radius: 4px;
    cursor: pointer;
    width: 100%;
    transition: background-color 0.2s;
}

button[type="submit"]:hover {
    background-color: #9965f4;
}

button[type="submit"]:focus {
    outline: 2px solid #ffffff;
    outline-offset: 2px;
}

const { useState } = React;

const RadioGroup = ({ options, name, label, value, onChange }) => {
  return (
    <div className="form-field">
      <fieldset style={{ border: 'none', padding: 0, margin: 0 }}>
        <legend style={{ fontSize: '1.1rem', marginBottom: '1rem', fontWeight: '500' }}>
          {label}
        </legend>
        <div className="radio-group" role="radiogroup">
          {options.map((option) => (
            <label key={option} className="radio-option">
              <input
                type="radio"
                name={name}
                value={option}
                checked={value === option}
                onChange={(e) => onChange(e.target.value)}
                required
              />
              <span className="radio-label">{option}</span>
            </label>
          ))}
        </div>
      </fieldset>
    </div>
  );
};

const NotificationForm = () => {
  const [preference, setPreference] = useState('');

  const handleSubmit = (e) => {
    e.preventDefault();
    alert(`You selected: ${preference}`);
  };

  return (
    <div className="container">
      <h1>Notification Settings</h1>
      <form onSubmit={handleSubmit}>
        <RadioGroup
          label="How do you prefer to receive notifications?"
          name="notification-preference"
          options={['Email', 'SMS', 'Push Notifications']}
          value={preference}
          onChange={setPreference}
        />
        <button type="submit">Submit</button>
      </form>
    </div>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<NotificationForm />);

